import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-data-engineering-l4-001', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Quality', question: 'What is data-centric AI and how does it shift the focus from model improvement to data improvement?', options: ['Data-centric AI ignores model selection entirely', 'Data-centric AI iteratively improves the training data (fixing labels, removing noise, adding underrepresented examples) rather than changing model architecture. Andrew Ng\'s research showed that for many real-world problems, improving data quality yields larger accuracy gains than model changes. Key practices: systematic error analysis to identify data issues, consistent labeling guidelines, data augmentation for weak slices, and automated data quality monitoring', 'Data-centric AI focuses on building larger models', 'Data quality has no impact on model performance'], correctAnswer: 1, explanation: 'Model-centric approach: fix data → iterate on model architecture/hyperparameters. Data-centric approach: fix model → iterate on data quality. For production ML: often 80% of time is spent on data issues. Techniques: (1) label auditing (use model predictions to surface likely mislabeled examples), (2) slice analysis (find underperforming subgroups and add data), (3) data augmentation for underrepresented cases, (4) consistent labeling (inter-annotator agreement > 0.9).', tags: ['data-centric', 'data-quality', 'label-quality', 'iterative-improvement'] },
  { id: 'ai-engineer-data-engineering-l4-002', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Feature Engineering', question: 'What is feature crossing and why is it important for linear models but less critical for tree-based models?', options: ['Tree-based models cannot learn feature interactions', 'Feature crossing always degrades model performance', 'Feature crossing creates new features by combining existing ones (e.g., latitude × longitude → neighborhood). Linear models cannot learn feature interactions, so explicit crosses are essential. Tree-based models inherently learn interactions through hierarchical splits but may still benefit from pre-computed crosses for efficiency. Deep learning learns interactions via hidden layers but can benefit from engineered crosses for faster convergence on tabular data', 'Feature crossing is only used in deep learning'], correctAnswer: 2, explanation: 'Linear: y = w1·x1 + w2·x2 cannot model x1·x2 interaction. Adding feature x3 = x1·x2 enables this. Trees: split on x1 < 5 → split on x2 < 3 naturally captures the interaction region. But: a 3-way interaction requires 3 levels of splits, making it harder to learn. Pre-computed crosses help trees learn efficiently. In practice: Google\'s Wide & Deep model explicitly uses feature crosses in the "wide" component alongside deep embeddings. For tabular ML, careful feature engineering (crosses, ratios, aggregations) often beats raw features even with modern models.', tags: ['feature-crossing', 'interaction', 'linear-models', 'feature-engineering'] },
  { id: 'ai-engineer-data-engineering-l4-003', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'ETL', question: 'What is the ELT (Extract-Load-Transform) pattern and why has it replaced ETL for ML pipelines?', options: ['ETL is always better for ML pipelines', 'ELT and ETL are identical patterns', 'ELT requires more storage but no additional compute', 'ELT loads raw data into the data lake/warehouse first, then transforms in-place using the warehouse\'s compute (e.g., Spark, BigQuery, Snowflake). Unlike ETL which transforms before loading, ELT preserves raw data for future transformations, enables schema-on-read flexibility, and leverages modern cloud warehouse scalability. For ML: raw data preservation is critical because feature engineering requirements change as models evolve, and reprocessing historical data requires access to the original format'], correctAnswer: 3, explanation: 'ETL: transform in a staging server → load clean data into warehouse. Problem for ML: if you need a new feature later, you may not have the raw data to compute it. ELT: load everything raw → transform in the warehouse. Raw data is always available. Modern enablers: cheap cloud storage (S3/GCS at $0.02/GB/month), powerful query engines (BigQuery processes PBs), and data lake formats (Delta Lake, Iceberg enable ACID on data lakes). ML-specific benefit: data scientists can experiment with new feature transforms on raw data without waiting for the data engineering team to modify the ETL pipeline.', tags: ['elt', 'etl', 'data-lake', 'raw-data-preservation'] },
  { id: 'ai-engineer-data-engineering-l4-004', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Validation', question: 'How does Great Expectations enable automated data validation for ML pipelines?', options: ['Great Expectations only checks file formats', 'Great Expectations replaces the need for ML model monitoring', 'Data validation is only needed for the initial dataset, not ongoing batches', 'Great Expectations defines "expectations" as declarative data quality rules (column types, value ranges, distributions, uniqueness, regex patterns) that are validated against each data batch. For ML: expectations can include statistical properties (mean within range, correlation between features stable, no significant distribution shift from reference dataset). When expectations fail, the pipeline halts before corrupted data reaches model training, preventing silent model degradation'], correctAnswer: 3, explanation: 'Example expectations for an ML feature table: (1) expect_column_values_to_be_between("age", 0, 150), (2) expect_column_values_to_not_be_null("user_id"), (3) expect_column_mean_to_be_between("purchase_amount", 10, 100), (4) expect_column_pair_values_to_be_in_set("country", "currency", valid_pairs), (5) custom: expect feature distribution KL-divergence from reference < 0.1. Integration: runs as a pipeline step between data ingestion and model training. If any expectation fails: pipeline stops, alert fires, data team investigates. Prevents: null features causing NaN gradients, outliers from data pipeline bugs, schema drift from upstream changes.', tags: ['great-expectations', 'data-validation', 'quality-gates', 'pipeline'] },
  { id: 'ai-engineer-data-engineering-l4-005', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Labeling', question: 'What is the annotation disagreement problem and how should it be handled for ML training?', options: ['Annotator disagreement means the data is unusable', 'Disagreement should be resolved by always using one annotator\'s labels', 'All examples should have unanimous agreement', 'Annotation disagreement occurs when labelers assign different labels to the same example. Solutions: (1) measure inter-annotator agreement (Cohen\'s kappa, Krippendorff\'s alpha), (2) use majority voting with 3+ annotators for noisy tasks, (3) model label uncertainty using soft labels (probability distribution instead of hard labels), (4) identify and improve unclear annotation guidelines, (5) weight examples by annotator agreement during training. Disagreement often indicates genuine ambiguity that the model should learn to express as uncertainty'], correctAnswer: 3, explanation: 'Inter-annotator agreement below 0.7 kappa indicates problematic guidelines. Actions: (1) refine guidelines with examples of edge cases, (2) retrain annotators, (3) for genuinely ambiguous cases, use soft labels: if 2/3 annotators say positive, label = [0.33, 0.67] instead of hard [0, 1]. Training on soft labels improves model calibration (model learns that some examples are ambiguous). Platt et al. (2024) showed that learning from human disagreement improves model performance on subjective tasks (toxicity, sentiment) versus majority-vote hard labels. Use agreement as a data signal: high-agreement examples are "easy," disagreement examples are "hard" — weight appropriately.', tags: ['annotation', 'disagreement', 'inter-annotator', 'soft-labels'] },
  { id: 'ai-engineer-data-engineering-l4-006', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Streaming', question: 'What is Apache Flink\'s advantage over Spark Streaming for real-time ML feature computation?', options: ['Flink provides true event-time processing with native watermark handling, enabling accurate windowed aggregations even with late-arriving events. Unlike Spark Streaming\'s micro-batch approach (which adds minimum latency equal to batch interval), Flink processes events one-by-one with sub-second latency. For ML features like "transaction count in last 5 minutes," Flink\'s event-time semantics ensure accuracy regardless of processing delays or out-of-order events', 'Spark Streaming and Flink have identical capabilities', 'Flink cannot handle out-of-order events', 'Spark Streaming always has lower latency than Flink'], correctAnswer: 0, explanation: 'Spark Structured Streaming: processes in micro-batches (minimum 100ms intervals in practice). Flink: processes each event individually with state management. Key difference for ML features: event-time vs processing-time. A transaction at 10:00:00 arrives at 10:00:05 due to network delay. Spark micro-batch at 10:00:03 misses it; next batch at 10:00:06 processes it with wrong window assignment. Flink: watermark tracks event-time progress, assigns the event to the correct 10:00:00 window. For ML features requiring precise time-windowed aggregations (essential for fraud detection, recommendation freshness), Flink\'s event-time handling is superior.', tags: ['flink', 'spark-streaming', 'event-time', 'real-time-features'] },
  { id: 'ai-engineer-data-engineering-l4-007', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Lineage', question: 'Why is data lineage tracking essential for ML systems and how is it implemented?', options: ['Lineage tracking adds too much overhead for practical use', 'Data lineage tracks the complete provenance of every piece of data: which sources contributed, what transformations were applied, and which models consumed it. For ML: (1) debugging model quality issues (which data change caused the accuracy drop?), (2) reproducing training runs (exact dataset recreation), (3) impact analysis (if source X changes, which models are affected?), (4) regulatory compliance (GDPR right to know how data is processed). Implemented via metadata catalogs (DataHub, Amundsen) that capture transformation DAGs automatically', 'Data lineage is only useful for regulatory compliance', 'Data lineage only needs to track the final training dataset'], correctAnswer: 1, explanation: 'Lineage captures: Source DB → ETL job (Airflow DAG run #123, timestamp) → feature table v7 → training run #456 → model v2.1 → serving endpoint. Use cases: (1) Model debugging: model accuracy dropped → trace to training data → trace to feature table → find that ETL job had a bug → fix and retrain. (2) GDPR deletion: user requests data deletion → lineage shows all tables and models containing their data → delete/retrain. (3) Impact analysis: source API changing format → lineage shows 5 feature tables and 12 models affected → plan migration. Tools: OpenLineage (standard), Marquez, DataHub capture lineage from Airflow/Spark/dbt automatically via instrumentation.', tags: ['data-lineage', 'provenance', 'datahub', 'openlineage'] },
  { id: 'ai-engineer-data-engineering-l4-008', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Augmentation', question: 'What is the Mixup data augmentation technique and why does it improve model generalization?', options: ['Mixup only interpolates features, not labels', 'Mixup only works for image data', 'Mixup creates virtual training examples by linearly interpolating between pairs of existing examples: x_new = λ·x_i + (1-λ)·x_j, y_new = λ·y_i + (1-λ)·y_j, where λ is drawn from Beta(α,α). This encourages the model to learn linear relationships between training examples, reduces overfitting, and improves calibration. It works for images, text embeddings, and tabular data. The key insight: it regularizes the model to behave linearly between training examples', 'Mixup reduces model accuracy on clean test data'], correctAnswer: 2, explanation: 'Mixup (Zhang et al. 2018): sample λ ~ Beta(0.2, 0.2). Take two random training examples (x_i, y_i) and (x_j, y_j). Create: x = λ·x_i + (1-λ)·x_j, y = λ·y_i + (1-λ)·y_j. For images: pixel-wise blend (λ=0.3: 30% cat + 70% dog, label=[0.3 cat, 0.7 dog]). For tabular: feature-wise interpolation. Benefits: (1) regularization (reduces overfitting by 1-3% on ImageNet), (2) better calibration (model outputs smooth probabilities), (3) improved OOD robustness. Variants: CutMix (patch-based), Manifold Mixup (interpolate hidden representations), and TokenMix for NLP.', tags: ['mixup', 'data-augmentation', 'regularization', 'interpolation'] },
  { id: 'ai-engineer-data-engineering-l4-009', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Formats', question: 'Why is Apache Parquet preferred over CSV and JSON for ML training data?', options: ['CSV is always faster to read than Parquet', 'Parquet and CSV have identical read performance', 'Parquet uses columnar storage enabling: (1) reading only needed columns without scanning entire rows (critical when datasets have 1000+ features but you need 50), (2) efficient compression per column (dictionary encoding for categoricals, delta for timestamps — 5-10x smaller than CSV), (3) predicate pushdown (skip row groups whose statistics exclude the filter range), (4) strong typing (no parsing ambiguity). For ML: training on Parquet is 3-10x faster than CSV due to reduced I/O and native integration with Spark, PyArrow, and Polars', 'Parquet cannot store string columns'], correctAnswer: 2, explanation: 'CSV: row-oriented, no types, no compression, reading 3 columns from 1000 requires reading all 1000. JSON: nested but verbose, parsing overhead. Parquet: columnar, typed, compressed, with row group statistics (min/max per column per group). Example: 1TB CSV dataset, need columns A, B, C out of 200. CSV: read 1TB. Parquet: read ~15GB (3/200 columns × compression). With predicate pushdown (WHERE A > 100): Parquet skips row groups where max(A) < 100, reading even less. For ML: pd.read_parquet("data.parquet", columns=["feature1", "feature2", "label"]) is 10x faster than pd.read_csv for large datasets. Delta Lake and Iceberg add ACID transactions on top of Parquet.', tags: ['parquet', 'columnar', 'csv', 'data-formats'] },
  { id: 'ai-engineer-data-engineering-l4-010', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Deduplication', question: 'Why is training data deduplication critical for ML model quality and what methods are used at scale?', options: ['Deduplication only matters for text data, not images', 'Duplicates cause: (1) memorization of specific examples (model regurgitates training data), (2) evaluation contamination (if duplicates appear in both train and test), (3) wasted compute on redundant examples, (4) bias toward duplicated subpopulations. At scale: exact dedup via hash-based methods (O(N)), near-dedup via MinHash + LSH (estimates Jaccard similarity, O(N) expected), semantic dedup via embedding clustering. Deduplication typically improves model quality by 5-15% while reducing dataset size by 20-60%', 'Duplicate data always improves model robustness', 'Deduplication always reduces model accuracy'], correctAnswer: 1, explanation: 'Methods: (1) Exact: SHA-256 hash of content → group by hash → keep one per group. Fast O(N) but misses near-duplicates (same content with minor formatting differences). (2) MinHash + LSH: represent each document as a set of n-grams → compute MinHash signature (K hash functions) → LSH groups similar signatures into buckets → check bucket collisions. Jaccard similarity > 0.8 → duplicate. O(N) expected time. (3) Suffix array: find all duplicate substrings of length ≥ K across the corpus. Used by Lee et al. (2022) for deduplicating C4. (4) Semantic: embed each document → cluster → remove documents too close to cluster center. Results: deduplicating C4 improved LM perplexity by ~10% (Lee et al. 2022). RefinedWeb, Dolma, RedPajama all use multi-stage dedup.', tags: ['deduplication', 'minhash', 'data-quality', 'near-duplicate'] },
  { id: 'ai-engineer-data-engineering-l4-011', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Lake', question: 'What are the key differences between Delta Lake, Apache Iceberg, and Apache Hudi for ML data lakes?', options: ['ACID transactions are not needed for ML data lakes', 'These formats only work with Apache Spark', 'All three table formats are identical', 'All three add ACID transactions and time-travel to data lakes. Delta Lake: deep Spark integration, Databricks-backed, excellent for Spark-heavy ML workflows. Iceberg: most vendor-neutral, strong schema evolution, used by Netflix for diverse engine support. Hudi: strongest incremental processing, copy-on-write and merge-on-read modes for different read/write patterns. For ML: time-travel enables exact dataset recreation for reproducibility, and ACID transactions prevent training on partially-written data'], correctAnswer: 3, explanation: 'ML-specific features: (1) Time travel: Delta/Iceberg/Hudi let you query data as of any timestamp → train model on exact dataset from 2024-01-15 for reproducibility. (2) Schema evolution: add new feature columns without rewriting the entire table. (3) Partition pruning: only read data partitions relevant to the training window. (4) ACID: concurrent writes (feature pipeline writing while training job reads) are safe — no corrupt half-written files. Differences: Delta requires Spark (though delta-rs enables Python/Rust). Iceberg works with Spark, Trino, Flink, Dremio — best for polyglot environments. Hudi: best for streaming upserts (CDC from databases). Most companies choose based on their existing engine ecosystem.', tags: ['delta-lake', 'iceberg', 'hudi', 'data-lake'] },
  { id: 'ai-engineer-data-engineering-l4-012', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Feature Store', question: 'What is the training-serving skew problem and how do feature stores prevent it?', options: ['Training-serving skew is automatically prevented by using the same model', 'Training-serving skew occurs when features have different values during training vs serving due to: (1) different code paths (Python for training, Java for serving), (2) different aggregation windows (batch uses full history, serving uses recent window), (3) timing differences (feature computed at training time vs real-time). Feature stores solve this by: defining features once in a shared registry, computing consistently for both batch (training) and online (serving), and providing point-in-time correct joins', 'Feature stores only solve the storage problem, not skew', 'Training-serving skew is a minor issue that rarely affects models'], correctAnswer: 1, explanation: 'Skew example: "user_avg_purchase_last_30d" — training pipeline computes this in Spark using exact 30-day window with all transactions. Serving computes this in a Java service using a Redis counter that sometimes misses transactions (race condition). Result: training sees value=45.20, serving sees value=43.50. The model learned patterns based on the Spark value, but serves with the Java value. Feature stores fix this: (1) define the feature once, (2) materialize to offline store (Spark-computed, for training) and online store (Redis, for serving) using the same logic, (3) Feast/Tecton ensure identical computation paths. Monitoring: compare offline vs online feature distributions; divergence indicates skew.', tags: ['training-serving-skew', 'feature-store', 'consistency', 'feast'] },
  { id: 'ai-engineer-data-engineering-l4-013', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Synthetic Data', question: 'When should synthetic data be used for ML training and what are its limitations?', options: ['Synthetic data has no privacy benefits over real data', 'Synthetic data always produces better models than real data', 'Synthetic data should completely replace real data', 'Synthetic data is valuable when: (1) real data is scarce (rare diseases, new product categories), (2) privacy prevents using real data (medical records, financial data), (3) specific edge cases need amplification (rare failure modes), (4) labeling is expensive (autonomous driving scenarios). Limitations: synthetic data may not capture real-world complexity (distribution gap), models can overfit to synthetic patterns, and evaluation must always use real data. Mixing synthetic + real data typically outperforms either alone'], correctAnswer: 3, explanation: 'Synthetic data generation methods: (1) Rule-based: generate tabular data using statistical distributions and business rules, (2) GAN/diffusion: generate realistic images/text, (3) Simulation: game engines for autonomous driving, physics simulators for robotics, (4) LLM-generated: GPT-4 generates training examples for NLP tasks. Distribution gap: synthetic medical images may miss rare pathologies, synthetic text may lack real-world messiness. Best practice: use real data as the primary source, augment with synthetic data for underrepresented classes/scenarios, and always evaluate on real data. Companies like Gretel, Mostly AI, and Synthesis AI specialize in privacy-safe synthetic data generation with distribution matching.', tags: ['synthetic-data', 'privacy', 'data-augmentation', 'distribution-gap'] },
  { id: 'ai-engineer-data-engineering-l4-014', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Contracts', question: 'What are data contracts and how do they prevent ML pipeline failures?', options: ['Schema validation alone is sufficient for data quality', 'Data contracts are formal specifications between data producers and consumers defining: schema (column names/types), quality rules (completeness, freshness, ranges), SLAs (data available by when), and semantic meaning. For ML: they prevent silent data corruption where upstream schema changes break feature computation without errors. Contract enforcement at pipeline boundaries catches violations before they corrupt model training, with automated alerting to both producer and consumer teams', 'Data contracts are legal agreements between companies', 'Data contracts add overhead without practical benefit'], correctAnswer: 1, explanation: 'Without contracts: upstream team renames a column → feature pipeline produces nulls → model trains on corrupted features → production accuracy drops days later → investigation takes days. With contracts: producer and consumer agree on schema + constraints → enforcement tool rejects non-conforming data → immediate alert → fix before any model is affected. Contract specification example: { "schema": {"user_id": "string", "amount": "float64"}, "quality": {"amount_range": [0, 10000], "null_rate_max": 0.01, "freshness_max": "1h"} }. Tools: Soda, Great Expectations, dbt contracts, custom validation. Governance: data product teams own their contracts; breaking changes require versioning and migration periods.', tags: ['data-contracts', 'schema', 'pipeline-reliability', 'quality-gates'] },
  { id: 'ai-engineer-data-engineering-l4-015', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Sampling', question: 'What sampling strategies should be used for creating representative ML training datasets from large data lakes?', options: ['Only the most recent data should be used for training', 'Random sampling always produces representative datasets', 'Strategies beyond random sampling: (1) stratified sampling (maintain class proportions), (2) importance sampling (oversample rare but important events), (3) time-based sampling (recent data weighted more for temporal patterns), (4) diversity sampling (maximize coverage of feature space), (5) active learning-inspired (select examples near decision boundaries). Random sampling fails when: classes are imbalanced, certain time periods are critical, or rare edge cases must be included. The sampling strategy should match the model\'s intended use case distribution', 'Sampling strategy has no impact on model quality'], correctAnswer: 2, explanation: 'Example: fraud detection from 1B transactions. Random sample of 1M: ~0.1% fraud (1000 fraud cases — too few to learn from). Stratified: sample 500K non-fraud + 500K fraud → balanced but overrepresents fraud for training (calibrate predictions post-hoc). Importance: sample proportionally but weight rare events higher in loss function. Time-based: more recent transactions weighted higher (fraud patterns evolve). Diversity: ensure coverage of all merchant categories, geographies, transaction types. Active learning: identify uncertain regions in feature space and sample from there. In practice: combine strategies — stratified by class × time period × geography, with importance weighting.', tags: ['sampling', 'stratified', 'importance-sampling', 'dataset-creation'] },
  { id: 'ai-engineer-data-engineering-l4-016', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'PII Handling', question: 'What techniques are used for handling PII in ML training data while preserving utility?', options: ['PII handling is only required in healthcare, not other industries', 'Anonymization always makes data completely safe', 'PII should simply be deleted from all training data', 'PII handling techniques: (1) pseudonymization (replace names with consistent fake names — preserves relationships), (2) k-anonymity (generalize quasi-identifiers so each record is indistinguishable from k-1 others), (3) differential privacy (add calibrated noise during training — mathematical privacy guarantee), (4) tokenization (replace PII with tokens, maintain mapping separately), (5) synthetic data generation (generate statistically similar data without real individuals). Choice depends on privacy requirements, downstream task needs, and regulatory context'], correctAnswer: 3, explanation: 'Technique selection: (1) For NLP training: NER-based PII detection → replace with type tokens ([PERSON], [EMAIL], [PHONE]) or generate fake replacements (preserves syntax patterns). (2) For tabular: k-anonymity + l-diversity for quasi-identifiers (age → age range, zip → first 3 digits). (3) For model training with formal guarantees: DP-SGD during training → (ε, δ)-differential privacy. (4) For analytics/feature engineering: tokenization (reversible with secure key) or aggregation (individual → cohort level). Pitfalls: naive anonymization fails — Netflix prize dataset was de-anonymized via auxiliary data; simple k-anonymity can be broken by homogeneity attacks. For LLMs: PII in training data can be memorized and regurgitated — combine PII scrubbing of training data with output PII filters.', tags: ['pii', 'privacy', 'anonymization', 'differential-privacy'] },
  { id: 'ai-engineer-data-engineering-l4-017', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Versioning', question: 'How does content-addressable storage enable efficient data versioning for ML?', options: ['Content-addressable storage is too slow for large datasets', 'Data versioning requires storing complete copies of each version', 'Content-addressable storage requires duplicating all data for each version', 'Content-addressable storage identifies data by its content hash, not location. When a dataset is "versioned," only the metadata (hash references) changes — unchanged files are shared between versions via the same hash. This enables: O(1) deduplication, efficient branching (new version = new metadata pointing to mostly same hashes), and instant diffs (compare hash lists). DVC and LakeFS use this approach to version terabyte-scale datasets with minimal storage overhead'], correctAnswer: 3, explanation: 'Example: dataset v1 has 10,000 files (100GB). Version v2 modifies 100 files. Content-addressable: compute SHA-256 for each file → v2 metadata references 9,900 unchanged hashes + 100 new hashes. Storage: 100GB (v1) + 1GB (new files in v2) = 101GB total, not 200GB. DVC: "dvc add data/" computes hashes, stores data in remote (S3), tracks .dvc files in Git. "dvc checkout v1" fetches exactly the files for v1. LakeFS: provides Git-like branching for data lakes — branch, commit, merge data like code. For ML reproducibility: Git commit abc123 + DVC data hash xyz789 = exact reproducible experiment.', tags: ['content-addressable', 'data-versioning', 'dvc', 'deduplication'] },
  { id: 'ai-engineer-data-engineering-l4-018', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Web Scraping', question: 'What are the technical and legal considerations for building web-scraped ML training datasets?', options: ['All web content can be freely used for ML training', 'Technical: (1) respect robots.txt and rate limits, (2) handle dynamic JavaScript-rendered content (headless browsers), (3) deduplicate across crawls, (4) extract clean text from HTML (boilerplate removal), (5) detect and filter low-quality/spam content. Legal: (1) check terms of service, (2) respect copyright (fair use varies by jurisdiction), (3) EU AI Act requires transparency about training data sources, (4) opt-out mechanisms for data subjects. Quality: web data requires extensive filtering (language detection, content quality scoring, PII removal, toxicity filtering)', 'Web scraping for ML training has no legal considerations', 'Web-scraped data is always higher quality than curated datasets'], correctAnswer: 1, explanation: 'Building a training dataset from web data: (1) Crawling: use Common Crawl or custom crawler. Rate limit to 1 request/second per domain. Respect robots.txt. (2) Extraction: resiliparse/trafilatura for clean text extraction from HTML (removes navigation, ads, boilerplate). (3) Filtering: language detection (fasttext), quality scoring (perplexity from a reference LM — high perplexity = low quality), toxicity filtering, PII removal (regex + NER). (4) Deduplication: MinHash for near-duplicates, URL-level dedup. (5) Legal: document data sources for regulatory compliance. C4, RefinedWeb, and Dolma are examples of curated web datasets with published filtering methodologies. The NYT vs OpenAI lawsuit (2023) highlights unresolved copyright questions around using web content for LLM training.', tags: ['web-scraping', 'data-collection', 'filtering', 'legal'] },
  { id: 'ai-engineer-data-engineering-l4-019', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Change Data Capture', question: 'How does Change Data Capture (CDC) enable real-time ML feature computation from databases?', options: ['CDC only works with MySQL databases', 'CDC adds significant load to the source database', 'CDC reads the database transaction log (binlog/WAL) to capture inserts, updates, and deletes as they happen, streaming them to Kafka without querying the database. For ML: (1) real-time features can be computed from database changes (new order → update user purchase velocity), (2) feature stores stay synchronized with source databases, (3) training datasets can be reconstructed at any point in time by replaying the change stream. Debezium is the standard open-source CDC tool', 'CDC requires polling the database for changes'], correctAnswer: 2, explanation: 'CDC pipeline: Postgres WAL → Debezium → Kafka → Flink (compute features) → Redis (online store) + S3 (offline store). Example: user_table changes → CDC captures: {op: "update", before: {balance: 1000}, after: {balance: 500}, ts: "..."}. Flink computes: balance_change_velocity, large_withdrawal_flag → writes to Redis for real-time fraud scoring. Benefits over polling: (1) sub-second latency (vs minutes for polling), (2) no load on source DB (reads log, not queries), (3) captures all changes including deletes (polling can miss rapid changes), (4) maintains ordering guarantees (log is ordered). For ML training data: replay CDC events up to timestamp T to reconstruct the exact database state at time T — essential for point-in-time correct feature computation.', tags: ['cdc', 'debezium', 'real-time', 'database-sync'] },
  { id: 'ai-engineer-data-engineering-l4-020', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Orchestration', question: 'What is dbt (data build tool) and how does it fit into ML data pipelines?', options: ['dbt replaces Airflow for all orchestration needs', 'dbt can only run SQL, making it useless for ML', 'dbt enables SQL-based data transformation with software engineering best practices: version control, testing, documentation, and modularity. For ML: dbt transforms raw data into clean feature tables in the data warehouse, with built-in testing (uniqueness, not-null, relationship checks) and documentation. It handles the Silver→Gold transformation in medallion architecture. dbt does not replace Airflow (which orchestrates the full pipeline including training), but handles the data transformation layer efficiently', 'dbt replaces the need for feature stores'], correctAnswer: 2, explanation: 'dbt in ML pipeline: Raw data (Bronze) → dbt models (SQL transformations) → Feature tables (Gold) → ML training. Example: dbt model `user_features.sql`: SELECT user_id, AVG(purchase_amount) OVER (PARTITION BY user_id ORDER BY ts ROWS 30 PRECEDING) as avg_purchase_30d FROM transactions. dbt adds: (1) tests: unique user_id, avg_purchase_30d > 0, (2) documentation: auto-generated lineage graph, (3) incremental models: only process new data since last run, (4) version control: all SQL in Git. Integration: Airflow triggers dbt run → dbt transforms data → Airflow triggers model training on dbt output tables. dbt-osmosis and dbt-ml extensions add ML-specific capabilities (feature documentation, metric definitions).', tags: ['dbt', 'sql-transformation', 'data-pipeline', 'testing'] },
  { id: 'ai-engineer-data-engineering-l4-021', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Embedding Pipeline', question: 'How should a document embedding pipeline be designed for large-scale RAG systems?', options: ['Scalable embedding pipeline: (1) document ingestion (watch S3 bucket or receive webhooks for new docs), (2) parsing and chunking (extract text from PDF/HTML/DOCX, split into chunks with overlap), (3) batch embedding (GPU-accelerated, process thousands of chunks in batches), (4) index upsert (write embeddings to vector database), (5) metadata enrichment (extract entities, topics, dates for filtering). The pipeline should be incremental (only process new/modified documents) and include quality checks (chunk length validation, embedding norm checks)', 'Documents should be embedded one at a time as they are uploaded', 'Embedding pipelines do not need to be incremental', 'Document parsing is a trivial step that needs no special handling'], correctAnswer: 0, explanation: 'Pipeline architecture: S3 event → SQS queue → worker fleet: (a) parse document (Unstructured.io for multi-format), (b) chunk (recursive text splitter, 512 tokens, 50 overlap), (c) embed chunks (batch of 64 → GPU embedding model → 768-d vectors), (d) upsert to Pinecone/Qdrant with metadata (doc_id, chunk_idx, source, date). Incremental: track processed document hashes, skip unchanged documents. Quality gates: reject chunks < 50 tokens (likely noise), flag chunks with unusual embedding norms. Scale: 1M documents = ~10M chunks × 768 floats × 4 bytes = ~30GB of embeddings. Processing: single A10G with optimized embedding model processes ~10K chunks/minute. For 1M docs: ~16 hours. With 4 GPUs: ~4 hours. Scheduling: nightly full reindex + real-time incremental for new uploads.', tags: ['embedding-pipeline', 'rag', 'document-processing', 'batch-processing'] },
  { id: 'ai-engineer-data-engineering-l4-022', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Schema Evolution', question: 'How should ML pipelines handle schema evolution when feature definitions change?', options: ['All schema changes require immediate retraining of all models', 'Schema evolution strategies: (1) backward compatible (add new columns with defaults — existing consumers unaffected), (2) forward compatible (consumers ignore unknown columns), (3) breaking changes (rename/remove columns — requires coordinated migration). For ML: adding new features is backward compatible (old models ignore them). Removing features requires retraining all dependent models. Schema registries (Confluent, AWS Glue) enforce compatibility rules and version schemas. Feature stores should support feature versioning so old and new feature definitions coexist during migration', 'Schema changes should never occur in production', 'Schema evolution is only relevant for database systems, not ML'], correctAnswer: 1, explanation: 'ML schema evolution scenarios: (1) Add feature: add "user_engagement_score" column. Old models ignore it, new models can use it. Backward compatible — no migration needed. (2) Change feature type: "age" from int to float. May break deserializers. Need: update schema version, validate all consumers handle float, migrate. (3) Remove feature: "deprecated_feature" removed. All models using it must be retrained first. Process: (a) mark feature as deprecated in registry, (b) retrain all dependent models without it, (c) verify no active model depends on it, (d) remove column. Schema registries enforce rules: new versions must be backward compatible unless explicitly approved. Feature stores maintain feature versions: v1 and v2 of "user_score" coexist, models pin to specific versions.', tags: ['schema-evolution', 'backward-compatible', 'feature-versioning', 'migration'] },
  { id: 'ai-engineer-data-engineering-l4-023', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Testing', question: 'What types of data tests should run in an ML pipeline CI/CD system?', options: ['Data tests slow down pipelines without providing value', 'Only the training data needs testing, not intermediate transformations', 'Only model accuracy tests are needed in ML CI/CD', 'Data tests in ML CI/CD: (1) schema tests (column presence, types, no unexpected columns), (2) volume tests (expected row count range, no empty tables), (3) freshness tests (data timestamp within expected range), (4) distribution tests (feature distributions within expected bounds, no sudden shifts from reference), (5) relationship tests (foreign key validity, referential integrity), (6) business rule tests (domain-specific constraints like prices > 0). These run before model training and block the pipeline if violations are detected'], correctAnswer: 3, explanation: 'Testing hierarchy in ML CI/CD: Code changes trigger: (1) Unit tests: data transformation functions produce expected output for test inputs. (2) Schema tests: output tables match expected schemas. (3) Data quality tests (Great Expectations): feature distributions within bounds, null rates below threshold, value ranges valid. (4) Integration tests: end-to-end pipeline produces valid training dataset. (5) Model tests: model trains successfully, metrics exceed thresholds, no regression vs baseline. Gate rules: any schema test failure → block pipeline. Distribution drift > 2 standard deviations → alert but allow with manual approval. Model regression > 1% → block deployment. Test data: maintain a fixed validation dataset versioned alongside code for reproducible testing.', tags: ['data-testing', 'cicd', 'quality-gates', 'great-expectations'] },
  { id: 'ai-engineer-data-engineering-l4-024', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Distributed Processing', question: 'When should ML data processing use Spark versus single-machine tools like Polars or DuckDB?', options: ['Single-machine tools cannot process datasets larger than RAM', 'Use single-machine tools (Polars, DuckDB) when: data fits in memory (<100GB), processing is simple (filter, aggregate, join), and team wants minimal infrastructure. Use Spark when: data exceeds single-machine capacity (TB+), processing requires shuffle-heavy operations across many nodes, or integration with existing Spark ecosystem (Delta Lake, ML pipelines) is valuable. Polars can be 5-10x faster than Spark for medium datasets due to eliminated overhead of cluster coordination and serialization', 'DuckDB is only useful for analytical queries, not data transformation', 'Spark is always the best choice for data processing'], correctAnswer: 1, explanation: 'Decision framework: <10GB → Pandas/Polars (fastest, simplest). 10-100GB → Polars/DuckDB (memory-mapped, out-of-core support, no cluster overhead). 100GB-10TB → Spark or Dask (distributed, but significant overhead for small jobs). >10TB → Spark on cluster (designed for this scale). Polars advantages over Spark for medium data: (1) no JVM overhead (Rust-based), (2) no serialization/deserialization between nodes, (3) query optimization via lazy evaluation, (4) true multi-threaded execution on all CPU cores. DuckDB advantages: SQL interface, embedded (no server), column-oriented, works on Parquet files directly. In practice: many ML teams use DuckDB/Polars for feature exploration and Spark only for production-scale jobs.', tags: ['spark', 'polars', 'duckdb', 'distributed-processing'] },
  { id: 'ai-engineer-data-engineering-l4-025', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Cataloging', question: 'What role do data catalogs play in ML systems and what metadata should they track?', options: ['Data catalogs enable ML teams to discover and understand available data. Key metadata: (1) schema and sample data, (2) data quality scores and freshness, (3) lineage (where data comes from and where it goes), (4) ownership (who to contact about issues), (5) usage statistics (which models/pipelines use this data), (6) ML-specific: which features are derived from this table, feature importance in deployed models, data sensitivity classification. Tools like DataHub, Amundsen, and OpenMetadata integrate with ML platforms to provide searchable, documented data discovery', 'Data catalogs are only needed for data governance teams', 'Data catalogs are redundant if you have a feature store', 'Only database administrators need access to data catalogs'], correctAnswer: 0, explanation: 'Without a catalog: ML engineer needs user demographic data → asks 5 teams → finds 3 different tables → doesn\'t know which is authoritative or fresh. With a catalog: search "user demographics" → find the canonical table with: schema, owner (user-profile team), freshness (updated hourly), quality score (99.8% completeness), downstream consumers (fraud model, recommendation model), and sample values. ML-specific additions: (1) feature documentation: what each feature means, how it\'s computed, valid ranges, (2) model dependencies: which models use which tables (impact analysis for schema changes), (3) experiment tracking integration: link training runs to specific dataset versions. Discovery reduces time-to-first-model from weeks to days for new ML projects.', tags: ['data-catalog', 'metadata', 'discovery', 'datahub'] },
  { id: 'ai-engineer-data-engineering-l4-026', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Partitioning', question: 'How should ML training data be partitioned for efficient access and processing?', options: ['Partition by time (date/month) for temporal ML data — enables efficient window queries for time-based features and training data selection. Additional partitions by frequently filtered columns (region, category) reduce scan scope. For ML: date partitioning enables incremental training (only load recent partitions), efficient point-in-time queries, and data lifecycle management (archive old partitions). Over-partitioning (too many small files) hurts performance due to file listing overhead and suboptimal Parquet row groups', 'Partitioning only benefits query engines, not ML training', 'Data should never be partitioned', 'Random partitioning is optimal for all ML use cases'], correctAnswer: 0, explanation: 'ML partition strategy: Primary: date (enables temporal queries). Secondary: depends on use case — category for recommendation models, region for geo-specific models. Example: s3://data/transactions/date=2024-01-15/region=US/. Query "last 30 days of US transactions" reads 30 partitions × 1 region instead of scanning entire table. For incremental training: "train on data since last training date" → read only new date partitions. Anti-patterns: (1) too many partitions (1 file per minute = millions of small files → slow listing), (2) partitioning by high-cardinality column (user_id → millions of partitions). Optimal partition size: 128MB-1GB per partition file for Parquet.', tags: ['partitioning', 'temporal', 'data-organization', 'parquet'] },
  { id: 'ai-engineer-data-engineering-l4-027', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Active Learning Pipeline', question: 'How should an active learning data pipeline be designed for production ML systems?', options: ['Active learning only works for classification tasks', 'Active learning requires offline manual selection of examples', 'Production active learning pipeline: (1) model serves predictions in production, (2) uncertainty estimation identifies low-confidence predictions, (3) these uncertain examples are routed to a labeling queue, (4) human annotators label the high-value examples, (5) new labeled data is added to the training set, (6) model is retrained on the enriched dataset. This creates a data flywheel that efficiently targets labeling budget on the most informative examples rather than random sampling, typically achieving the same model quality with 2-5x fewer labels', 'Active learning always requires more labels than random sampling'], correctAnswer: 2, explanation: 'Active learning loop: Serve → Identify uncertain → Queue for labeling → Label → Retrain → Serve improved model. Uncertainty strategies: (1) entropy-based: high output entropy = uncertain, (2) margin: small gap between top-2 class probabilities, (3) committee: multiple models disagree, (4) Bayesian: MC Dropout variance. Production implementation: (a) async logging of predictions + confidence, (b) batch selection of examples below confidence threshold, (c) routing to labeling platform (Label Studio, Scale AI), (d) quality assurance (inter-annotator agreement), (e) scheduled retraining incorporating new labels. Budget optimization: if labeling budget is 1000 examples/week, active learning selects the 1000 most informative vs random 1000 — equivalent to 3000-5000 random labels in model improvement.', tags: ['active-learning', 'data-pipeline', 'uncertainty', 'labeling'] },
  { id: 'ai-engineer-data-engineering-l4-028', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Compliance', question: 'How should ML data pipelines handle GDPR right-to-erasure (right to be forgotten) requests?', options: ['Simply deleting from the source database is sufficient', 'GDPR does not apply to ML training data', 'GDPR erasure requires: (1) identify all data stores containing the user\'s data (via data lineage tracking), (2) delete from source databases and derived tables, (3) remove from feature stores (both online and offline), (4) for trained models: if the model memorized user data, retraining may be needed — otherwise, demonstrate that model outputs don\'t reveal individual data. Data lineage is essential: without knowing where user data flows, complete deletion is impossible. Implement "deletion by design" with user_id-based partitioning and cryptographic erasure (encrypt per-user, delete key to effectively erase)', 'Trained ML models never need to be retrained for GDPR compliance'], correctAnswer: 2, explanation: 'GDPR erasure implementation: (1) User requests deletion → (2) Data lineage graph identifies all locations: source DB, feature store (Redis + offline store), training datasets, vector DB embeddings, log files. (3) Delete from all: source DB: DELETE WHERE user_id=X. Feature store: delete key from Redis + mark as deleted in offline store. Vector DB: delete user\'s embedded documents. Logs: anonymize or delete entries. (4) Models: if model was trained on this user\'s data and might memorize it (small dataset, frequent user), retrain. For large models trained on millions of users: individual contribution is negligible, no retraining needed. Document this reasoning. Cryptographic erasure: encrypt each user\'s data with a per-user key → deleting the key makes data unrecoverable without physically deleting files (efficient for immutable data stores like S3).', tags: ['gdpr', 'right-to-erasure', 'data-lineage', 'cryptographic-erasure'] },
  { id: 'ai-engineer-data-engineering-l4-029', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Observability', question: 'What is data observability and how does it differ from data quality monitoring?', options: ['Data observability eliminates the need for data quality tests', 'Data observability and data quality monitoring are identical', 'Data quality monitoring checks predefined rules (nulls < 5%, schema matches). Data observability provides deep visibility into data health through: (1) automatic anomaly detection on data freshness, volume, schema, distribution, and lineage without manual rule definition, (2) root cause analysis (which upstream change caused this anomaly?), (3) impact analysis (which downstream models/reports are affected?). Observability is proactive (detects unknown unknowns), while monitoring is reactive (checks known rules). Tools: Monte Carlo, Bigeye, Soda provide ML-powered anomaly detection on data pipelines', 'Only data engineers need data observability, not ML engineers'], correctAnswer: 2, explanation: 'Data monitoring: alert if null_rate("user_id") > 0. Data observability: automatically detect that user_id null rate went from 0.001% to 5% (anomaly), trace to the upstream ETL job that deployed a bug at 3am, and identify that the fraud model and recommendation model both consume this table and may be affected. Key pillars (adapted from software observability): (1) Freshness: is data arriving on time? (2) Volume: expected number of rows? (3) Distribution: feature distributions stable? (4) Schema: unexpected changes? (5) Lineage: end-to-end data flow visibility. Monte Carlo automatically learns normal patterns and alerts on deviations. For ML: data observability catches issues that would degrade model performance before they reach the training pipeline.', tags: ['data-observability', 'anomaly-detection', 'monte-carlo', 'data-health'] },
  { id: 'ai-engineer-data-engineering-l4-030', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Multimodal Data', question: 'What are the unique challenges of managing multimodal training data (text + images + audio)?', options: ['Multimodal challenges: (1) storage heterogeneity (text in Parquet, images as files, audio as WAV/MP3 — different optimal formats), (2) alignment (matching text captions to correct images requires reliable metadata), (3) scale (images/audio are 100-1000x larger than text per example), (4) quality filtering per modality (blurry images, garbled audio, mismatched pairs), (5) unified data loading (training requires synchronized loading of all modalities). Solutions: WebDataset (tar-based format for multimodal), Hugging Face Datasets with multiple columns, and custom data loading with multi-worker prefetching', 'Multimodal data management is identical to text-only management', 'All modalities should be stored in the same file format', 'Multimodal data requires no special quality filtering'], correctAnswer: 0, explanation: 'WebDataset format: pack (image.jpg, caption.txt, metadata.json) into tar files for sequential I/O. Benefits: efficient streaming from cloud storage (no random file access), natural sharding for distributed training, minimal metadata overhead. Data loading: PyTorch DataLoader with multiple workers prefetching and decoding different modalities in parallel. Quality filtering pipeline: (1) image: check resolution, aspect ratio, detect NSFW, OCR for text-in-image, (2) text: language detection, quality scoring, PII removal, (3) alignment: CLIP score between image and text (low CLIP = mismatched pair → filter). LAION-5B: 5.85B image-text pairs filtered from web crawls using CLIP score thresholds. Storage: separate hot (training) and cold (archive) tiers for cost management.', tags: ['multimodal-data', 'webdataset', 'data-loading', 'quality-filtering'] },
  { id: 'ai-engineer-data-engineering-l4-031', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Graph Data', question: 'How should graph-structured data be prepared for GNN training?', options: ['Graph data can be directly used in standard ML models without preparation', 'GNNs do not need feature engineering on graph data', 'Graph data preparation for GNNs: (1) construct the graph (define nodes, edges, and edge types from relational data), (2) generate node/edge features (aggregate attributes, compute graph statistics like degree/centrality), (3) handle heterogeneous graphs (different node types and edge types need separate feature processing), (4) split into train/val/test with care to avoid information leakage through graph connectivity (random node split leaks through message passing). Temporal graphs require time-aware splits where training only uses edges from the past', 'Train/test splits for graphs are identical to tabular data splits'], correctAnswer: 2, explanation: 'Graph construction from relational DB: users table + transactions table → bipartite graph (users ↔ merchants, edges = transactions with amount/time features). Node features: user (age, location, account_age), merchant (category, avg_price, rating). Feature engineering: PageRank, clustering coefficient, local triangle count — all computable with NetworkX/GraphTool. Splitting challenge: if node A (train) connects to node B (test), A\'s GNN features include information about B → leakage. Solutions: (1) inductive split: train GNN on subgraph, evaluate on completely unseen subgraph, (2) temporal split: train on edges before time T, evaluate on edges after T (standard for link prediction), (3) transductive with masking: mask test edges during training message passing. Libraries: PyG (PyTorch Geometric), DGL handle these patterns.', tags: ['graph-data', 'gnn', 'data-preparation', 'train-test-split'] },
  { id: 'ai-engineer-data-engineering-l4-032', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Cost Management', question: 'How should data storage costs be managed for ML systems with growing datasets?', options: ['Storage cost management: (1) tiered storage (hot: SSD for active training data, warm: HDD for recent data, cold: S3 Glacier for archives), (2) lifecycle policies (auto-move data to cheaper tiers after N days), (3) compression (Parquet with zstd compression: 5-10x vs raw CSV), (4) deduplication (content-addressed storage eliminates redundant copies), (5) selective retention (keep all data for regulated industries, sample older data for others), (6) compute-storage separation (scale storage independently of compute). Monitor storage growth rate and cost per GB across tiers', 'Data storage costs are negligible compared to compute', 'Store all data in the highest-performance tier indefinitely', 'All historical data should be deleted after model training'], correctAnswer: 0, explanation: 'Cost comparison (AWS, per GB/month): S3 Standard: $0.023. S3 Infrequent Access: $0.0125. S3 Glacier: $0.004. EBS SSD: $0.10. For 100TB ML data lake: all S3 Standard = $2,300/month. With tiering: 10TB hot ($230) + 30TB warm ($375) + 60TB cold ($240) = $845/month (63% savings). Lifecycle policies: auto-transition training data from Standard to IA after 30 days, to Glacier after 90 days. Keep metadata in Standard (tiny, always accessible). For ML: archive raw data to Glacier (needed for reproducibility/audits but rarely accessed), keep processed features in Standard/IA (accessed during training), cache active training data on local SSD (fastest training). Data compression: Parquet with zstd saves 70-90% vs CSV, reducing both storage and I/O costs.', tags: ['cost-management', 'tiered-storage', 'lifecycle-policies', 'compression'] },
  { id: 'ai-engineer-data-engineering-l4-033', language: 'ai-engineer', level: 'level4', category: 'Data Engineering for AI', subcategory: 'Data Mesh', question: 'What is the role of a "data product" in the data mesh paradigm for ML systems?', options: ['Only the central data team can create data products', 'A data product is the same as a database table', 'Data products eliminate the need for feature engineering', 'A data product is a self-contained unit of data with: (1) well-defined schema and documentation, (2) quality guarantees (SLAs for freshness, completeness, accuracy), (3) discoverability (registered in a data catalog), (4) access control (who can read/write), (5) ownership by a domain team responsible for its quality. For ML: data products serve as the interface between data engineering and ML teams — ML engineers consume data products rather than raw database tables, with contractual guarantees about data quality and schema stability'], correctAnswer: 3, explanation: 'Data mesh principle: treat data as a product. The payments domain team publishes a "transaction_events" data product with: schema (typed columns with descriptions), SLA (available within 5 minutes of transaction, 99.9% completeness), quality metrics (published on a dashboard), access interface (Kafka topic for streaming, Delta Lake table for batch), ownership (payments-data-team@company.com), and versioning (v2 with backward compatibility to v1). ML consumers: the fraud team builds features from this data product. If the payments team needs to change the schema, they must follow a deprecation process and notify all consumers. This decentralizes data ownership while maintaining interoperability. Key difference from a raw table: a data product has a quality contract and a responsible owner.', tags: ['data-product', 'data-mesh', 'ownership', 'sla'] },
];

export default questions;
